const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const geom = ee.Geometry.Polygon(
      [[-118.5, 34.05], [-118.5, 33.6], [-118.1, 33.6], [-118.1, 34.05]],
      null, false
    );
    const startDay = {month: 10, day: 1};
    const endDay = {month: 10, day: 24}; // exclusive to include up to 23rd

    // Helper: Build collection with fallback
    function buildCollection(start, end) {
      const offl = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
        .filterDate(start, end).filterBounds(geom);
      return offl.size().gt(0).conditional(
        offl,
        ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2')
          .filterDate(start, end).filterBounds(geom)
      );
    }

    function maskNO2(img) {
      const qa = img.select('qa_value');
      const mask = qa.gte(0.75);
      return img.updateMask(mask).select('tropospheric_NO2_column_number_density');
    }

    function getPeriod(year) {
      const start = ee.Date.fromYMD(year, startDay.month, startDay.day);
      const end = ee.Date.fromYMD(year, endDay.month, endDay.day);
      return {start, end};
    }

    async function yearStats(year) {
      const {start, end} = getPeriod(year);
      // Try OFFL first, fallback to NRTI if OFFL empty
      const offl = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
        .filterDate(start, end).filterBounds(geom);
      const offlSize = offl.size().getInfo();
      let used = 'OFFL';
      let col = offl;
      if (offlSize === 0) {
        const nrti = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2')
          .filterDate(start, end).filterBounds(geom);
        const nrtiSize = nrti.size().getInfo();
        if (nrtiSize === 0) {
          return {year, size: 0, used: 'None'};
        }
        col = nrti;
        used = 'NRTI';
      }
      const size = col.size().getInfo();

      const colMasked = col.map(maskNO2);
      const meanImg = colMasked.mean();

      const reduceArgs = {geometry: geom, scale: 3000, maxPixels: 1e9};
      const meanDict = meanImg.reduceRegion({reducer: ee.Reducer.mean(), ...reduceArgs}).getInfo();
      const countDict = meanImg.reduceRegion({reducer: ee.Reducer.count(), ...reduceArgs}).getInfo();
      const totalDict = ee.Image(1).reduceRegion({reducer: ee.Reducer.count(), ...reduceArgs}).getInfo();

      const meanVal = meanDict ? meanDict.tropospheric_NO2_column_number_density : null;
      const validCount = countDict ? countDict.tropospheric_NO2_column_number_density : 0;
      const totalCount = totalDict ? totalDict.constant : 0;

      return {
        year, size, used,
        mean: meanVal,
        validCount: validCount || 0,
        totalCount: totalCount || 0
      };
    }

    // Compute stats for 2018, 2019, 2021
    const y2018 = await yearStats(2018);
    const y2019 = await yearStats(2019);
    const y2021 = await yearStats(2021);

    // 2. Data Acquisition & Checks
    // C1: Empty collection for any year
    if (y2018.size === 0 || y2019.size === 0 || y2021.size === 0) {
      console.log(`2018 Images: ${y2018.size || 0} (Used: ${y2018.used || 'None'})`);
      console.log(`2019 Images: ${y2019.size || 0} (Used: ${y2019.used || 'None'})`);
      console.log(`2021 Images: ${y2021.size || 0} (Used: ${y2021.used || 'None'})`);
      console.log('Empty collection for at least one period.');
      console.log('C1');
      return;
    }

    function fmtYearLine(y) {
      const vpct = y.totalCount > 0 ? (100 * y.validCount / y.totalCount) : 0;
      const meanStr = (typeof y.mean === 'number') ? y.mean.toExponential(3) : 'null';
      return `Y${y.year}: Images=${y.size} (${y.used}), ValidPx=${y.validCount}/${y.totalCount} (${vpct.toFixed(1)}%), Mean=${meanStr} mol/m^2`;
    }

    console.log('Region: South Los Angeles bbox [-118.5,33.6]-[-118.1,34.05], Oct 1–23');
    console.log(fmtYearLine(y2018));
    console.log(fmtYearLine(y2019));
    console.log(fmtYearLine(y2021));

    // 3. Processing checks: C2 and C3
    // C2: No valid pixels after masking for any year
    if (y2018.validCount === 0 || y2019.validCount === 0 || y2021.validCount === 0) {
      console.log('No valid pixels after QA masking for at least one period.');
      console.log('C2');
      return;
    }

    // C3: Calculation failure if mean is null/NaN or outside plausible range
    function invalidMean(v) {
      if (v === null || v === undefined) return true;
      if (!isFinite(v)) return true;
      // Plausibility check for tropospheric NO2 (mol/m^2)
      return Math.abs(v) > 5e-3;
    }
    if (invalidMean(y2018.mean) || invalidMean(y2019.mean) || invalidMean(y2021.mean)) {
      console.log('Mean value invalid (null/NaN/out-of-range) for at least one period.');
      console.log('C3');
      return;
    }

    // 4. Final Comparison: Is 2021 lower than BOTH 2019 and 2018?
    const isLower = (y2021.mean < y2019.mean) && (y2021.mean < y2018.mean);
    console.log(`Comparison: 2021 (${y2021.mean.toExponential(3)}) vs 2019 (${y2019.mean.toExponential(3)}), 2018 (${y2018.mean.toExponential(3)})`);

    // 5. Final Answer
    console.log(isLower ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
